mod solution;

fn main() {
    let cases = [
    (r#"n=5 edges=(0,1),(0,2),(1,3),(2,4)"#, r#"0,1,1,2,2"#),
    (r#"n=4 edges=(0,1)"#, r#"0,1,-1,-1"#),
    (r#"
n=4 edges=(0,1)
"#, r#"0,1,-1,-1"#),
    (r#"  
n=5 edges=(0,1),(0,2),(1,3),(2,4)
  "#, r#"0,1,1,2,2"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS graph-bfs");
}
